type AppointmentForm = { patientId: string; doctorId: string; date: string; time: string; reason: string; department: string; notes: string; status: string };
const blankAppointment: AppointmentForm = { patientId: '', doctorId: '', date: today, time: '09:00', reason: '', department: 'Primary care', notes: '', status: 'Scheduled' };
function AppointmentModal({ editing, onClose, onSaved }: { editing?: Appointment; onClose: () => void; onSaved: () => void }) {
  const [form, setForm] = useState<AppointmentForm>(editing ? { patientId: String(editing.patientId), doctorId: String(editing.doctorId), date: editing.date.slice(0, 10), time: editing.time, reason: editing.reason, department: editing.department, notes: editing.notes ?? '', status: editing.status } : blankAppointment); const patients = useListPatients(); const doctors = useListDoctors(); const create = useCreateAppointment(); const update = useUpdateAppointment(); const pending = create.isPending || update.isPending;
  const submit = (event: FormEvent) => { event.preventDefault(); const data = { ...form, patientId: Number(form.patientId), doctorId: Number(form.doctorId), status: form.status as 'Scheduled' | 'Confirmed' | 'Completed' | 'Cancelled' | 'No-show' }; if (editing) update.mutate({ appointmentId: editing.id, data }, { onSuccess: onSaved }); else create.mutate({ data }, { onSuccess: onSaved }); };
  return <Modal title={editing ? 'Edit appointment' : 'Book an appointment'} eyebrow="Schedule care" onClose={onClose}><form className="modal-form" onSubmit={submit}><div className="form-grid"><label className="field"><span>Patient</span><select value={form.patientId} onChange={(event) => setForm({ ...form, patientId: event.target.value })} required data-testid="select-appointment-patient"><option value="">Choose patient</option>{(patients.data ?? []).map((item) => <option value={item.id} key={item.id}>{item.name}</option>)}</select></label><label className="field"><span>Clinician</span><select value={form.doctorId} onChange={(event) => setForm({ ...form, doctorId: event.target.value })} required data-testid="select-appointment-doctor"><option value="">Choose clinician</option>{(doctors.data ?? []).map((item) => <option value={item.id} key={item.id}>{item.name}</option>)}</select></label><Field label="Date" value={form.date} onChange={(date) => setForm({ ...form, date })} type="date" required testId="input-appointment-date" /><Field label="Time" value={form.time} onChange={(time) => setForm({ ...form, time })} type="time" required testId="input-appointment-time" /><Field label="Reason for visit" value={form.reason} onChange={(reason) => setForm({ ...form, reason })} required testId="input-appointment-reason" /><Field label="Department" value={form.department} onChange={(department) => setForm({ ...form, department })} required testId="input-appointment-department" /></div><SelectField label="Status" value={form.status} onChange={(status) => setForm({ ...form, status })} options={['Scheduled', 'Confirmed', 'Completed', 'Cancelled', 'No-show']} testId="select-appointment-status" /><label className="field"><span>Notes</span><textarea value={form.notes} onChange={(event) => setForm({ ...form, notes: event.target.value })} rows={3} data-testid="input-appointment-notes" /></label><div className="modal-actions"><Button variant="ghost" onClick={onClose}>Cancel</Button><Button type="submit" disabled={pending || !form.patientId || !form.doctorId} testId="button-save-appointment">{pending ? 'Saving…' : editing ? 'Save appointment' : 'Book appointment'}</Button></div></form></Modal>;
}

function AppointmentsPage() {
  const params = useParams<{ id?: string }>(); if (params.id) return <AppointmentDetailPage id={Number(params.id)} />;
  const [search, setSearch] = useState(''); const [status, setStatus] = useState(''); const [date, setDate] = useState(''); const [modal, setModal] = useState<'new' | Appointment | null>(null); const appointments = useListAppointments({ search: search || undefined, status: status || undefined, date: date || undefined }); const rows = appointments.data ?? []; const remove = useDeleteAppointment();
  const groups = useMemo(() => rows.reduce<Record<string, Appointment[]>>((acc, item) => { const key = item.date.slice(0, 10); (acc[key] ||= []).push(item); return acc; }, {}), [rows]);
  const saved = () => { setModal(null); queryClient.invalidateQueries({ queryKey: getListAppointmentsQueryKey() }); }; const deleted = (item: Appointment) => { if (window.confirm(`Delete the appointment for ${item.patientName}?`)) remove.mutate({ appointmentId: item.id }, { onSuccess: () => queryClient.invalidateQueries({ queryKey: getListAppointmentsQueryKey() }) }); };
  return <div className="page animate-rise"><PageHeader eyebrow="Care coordination" title="Appointments" description="A living schedule for every conversation, consultation, and follow-up." action={<Button onClick={() => setModal('new')} testId="button-add-appointment"><Plus size={16} /> Book appointment</Button>} /><div className="calendar-tools"><Toolbar search={search} setSearch={setSearch} placeholder="Search patient, clinician, or reason…" filters={['Scheduled', 'Confirmed', 'Completed']} onFilter={setStatus} /><label className="date-filter"><CalendarDays size={16} /><input type="date" value={date} onChange={(event) => setDate(event.target.value)} data-testid="input-appointment-date-filter" /></label></div>{appointments.isLoading ? <LoadingState /> : appointments.isError ? <ErrorState onRetry={() => appointments.refetch()} /> : rows.length === 0 ? <EmptyState icon={CalendarDays} title="The calendar is clear" description="No appointments match your current view." action={<Button onClick={() => setModal('new')} testId="button-empty-add-appointment"><Plus size={15} /> Book appointment</Button>} /> : <div className="calendar-list">{Object.entries(groups).sort(([a], [b]) => a.localeCompare(b)).map(([day, items]) => <section className="calendar-day" key={day}><div className="day-label"><span>{new Intl.DateTimeFormat('en', { weekday: 'short' }).format(new Date(day))}</span><b>{new Intl.DateTimeFormat('en', { day: '2-digit' }).format(new Date(day))}</b><small>{new Intl.DateTimeFormat('en', { month: 'short' }).format(new Date(day))}</small></div><div className="day-appointments">{items.map((item) => <div className="appointment-card panel" key={item.id}><AppointmentRow appointment={item} /><div className="appointment-actions"><button className="text-icon-button" onClick={() => setModal(item)} data-testid={`button-edit-appointment-${item.id}`}><Edit3 size={14} /> Edit</button><button className="text-icon-button danger-text" onClick={() => deleted(item)} data-testid={`button-delete-appointment-${item.id}`}><Trash2 size={14} /> Delete</button></div></div>)}</div></section>)}</div>}{modal && <AppointmentModal editing={modal === 'new' ? undefined : modal} onClose={() => setModal(null)} onSaved={saved} />}</div>;
}

