type RecordForm = { patientId: string; doctorId: string; date: string; diagnosis: string; symptoms: string; treatment: string; notes: string; followUp: string };
const blankRecord: RecordForm = { patientId: '', doctorId: '', date: today, diagnosis: '', symptoms: '', treatment: '', notes: '', followUp: '' };
function RecordModal({ editing, onClose, onSaved }: { editing?: MedicalRecord; onClose: () => void; onSaved: () => void }) {
  const [form, setForm] = useState<RecordForm>(editing ? { patientId: String(editing.patientId), doctorId: String(editing.doctorId), date: editing.date.slice(0, 10), diagnosis: editing.diagnosis, symptoms: editing.symptoms, treatment: editing.treatment, notes: editing.notes ?? '', followUp: editing.followUp ?? '' } : blankRecord); const patients = useListPatients(); const doctors = useListDoctors(); const create = useCreateMedicalRecord(); const update = useUpdateMedicalRecord(); const pending = create.isPending || update.isPending;
  const submit = (event: FormEvent) => { event.preventDefault(); const data = { ...form, patientId: Number(form.patientId), doctorId: Number(form.doctorId) }; if (editing) update.mutate({ recordId: editing.id, data }, { onSuccess: onSaved }); else create.mutate({ data }, { onSuccess: onSaved }); };
  return <Modal title={editing ? 'Update medical record' : 'Add medical record'} eyebrow="Clinical documentation" onClose={onClose}><form className="modal-form" onSubmit={submit}><div className="form-grid"><label className="field"><span>Patient</span><select value={form.patientId} onChange={(event) => setForm({ ...form, patientId: event.target.value })} required data-testid="select-record-patient"><option value="">Choose patient</option>{(patients.data ?? []).map((item) => <option value={item.id} key={item.id}>{item.name}</option>)}</select></label><label className="field"><span>Clinician</span><select value={form.doctorId} onChange={(event) => setForm({ ...form, doctorId: event.target.value })} required data-testid="select-record-doctor"><option value="">Choose clinician</option>{(doctors.data ?? []).map((item) => <option value={item.id} key={item.id}>{item.name}</option>)}</select></label><Field label="Date" value={form.date} onChange={(date) => setForm({ ...form, date })} type="date" required testId="input-record-date" /><Field label="Diagnosis" value={form.diagnosis} onChange={(diagnosis) => setForm({ ...form, diagnosis })} required testId="input-record-diagnosis" /></div><label className="field"><span>Symptoms</span><textarea value={form.symptoms} onChange={(event) => setForm({ ...form, symptoms: event.target.value })} rows={2} required data-testid="input-record-symptoms" /></label><label className="field"><span>Treatment</span><textarea value={form.treatment} onChange={(event) => setForm({ ...form, treatment: event.target.value })} rows={2} required data-testid="input-record-treatment" /></label><div className="form-grid"><Field label="Follow-up" value={form.followUp} onChange={(followUp) => setForm({ ...form, followUp })} testId="input-record-followup" /><Field label="Notes" value={form.notes} onChange={(notes) => setForm({ ...form, notes })} testId="input-record-notes" /></div><div className="modal-actions"><Button variant="ghost" onClick={onClose}>Cancel</Button><Button type="submit" disabled={pending || !form.patientId || !form.doctorId} testId="button-save-record">{pending ? 'Saving…' : editing ? 'Save record' : 'Add record'}</Button></div></form></Modal>;
}

function RecordsPage() {
  const params = useParams<{ id?: string }>(); if (params.id) return <RecordDetailPage id={Number(params.id)} />;
  const [search, setSearch] = useState(''); const [modal, setModal] = useState<'new' | MedicalRecord | null>(null); const records = useListMedicalRecords({ search: search || undefined }); const rows = records.data ?? [];
  const saved = () => { setModal(null); queryClient.invalidateQueries({ queryKey: getListMedicalRecordsQueryKey() }); };
  return <div className="page animate-rise"><PageHeader eyebrow="Clinical documentation" title="Medical records" description="A chronological, searchable source of truth for patient care." action={<Button onClick={() => setModal('new')} testId="button-add-record"><Plus size={16} /> Add record</Button>} /><Toolbar search={search} setSearch={setSearch} placeholder="Search by patient, diagnosis, or clinician…" />{records.isLoading ? <LoadingState /> : records.isError ? <ErrorState onRetry={() => records.refetch()} /> : rows.length === 0 ? <EmptyState icon={FileText} title="No records to review" description="Create the first medical record to begin the timeline." action={<Button onClick={() => setModal('new')} testId="button-empty-add-record"><Plus size={15} /> Add record</Button>} /> : <section className="panel record-list">{rows.map((record) => <Link href={`/records/${record.id}`} className="record-row" key={record.id} data-testid={`row-record-${record.id}`}><div className="record-date"><b>{new Intl.DateTimeFormat('en', { day: '2-digit' }).format(new Date(record.date))}</b><span>{new Intl.DateTimeFormat('en', { month: 'short' }).format(new Date(record.date))}</span></div><div className="record-main"><div><h2>{record.diagnosis}</h2><p>{record.patientName} · {record.doctorName}</p></div><div className="record-treatment"><span>Treatment</span><b>{record.treatment}</b></div></div><ArrowRight size={16} className="row-arrow" /></Link>)}</section>}{modal && <RecordModal editing={modal === 'new' ? undefined : modal} onClose={() => setModal(null)} onSaved={saved} />}</div>;
}

function RecordDetailPage({ id }: { id: number }) {
  const [, setLocation] = useLocation(); const record = useGetMedicalRecord(id, { query: { queryKey: getGetMedicalRecordQueryKey(id) } }); const [modal, setModal] = useState(false);
  if (record.isLoading) return <LoadingState />; if (record.isError || !record.data) return <ErrorState onRetry={() => record.refetch()} />; const data = record.data;
  return <div className="page animate-rise"><button className="back-link" onClick={() => setLocation('/records')} data-testid="button-back-records"><ArrowLeft size={15} /> Back to records</button><div className="detail-hero"><div><div className="eyebrow">Medical record · {formatDate(data.date)}</div><h1>{data.diagnosis}</h1><p>{data.patientName} · recorded by {data.doctorName}</p></div><Button variant="secondary" onClick={() => setModal(true)} testId="button-edit-record-detail"><Edit3 size={15} /> Edit record</Button></div><div className="record-detail-grid"><section className="panel prose-panel"><div className="eyebrow">Clinical note</div><h2>Symptoms</h2><p>{data.symptoms}</p><h2>Treatment plan</h2><p>{data.treatment}</p>{data.notes && <><h2>Notes</h2><p>{data.notes}</p></>}{data.followUp && <div className="follow-up"><Clock3 size={16} /><span>Follow-up</span><b>{data.followUp}</b></div>}</section><section className="panel detail-info"><div className="panel-head"><div><div className="eyebrow">Care context</div><h2>Record details</h2></div><FileText size={18} className="panel-icon" /></div><dl className="info-list"><div><dt>Patient</dt><dd><Link href={`/patients/${data.patientId}`} className="text-link">{data.patientName}</Link></dd></div><div><dt>Clinician</dt><dd>{data.doctorName}</dd></div><div><dt>Recorded</dt><dd>{formatDate(data.date)}</dd></div></dl></section></div>{modal && <RecordModal editing={data} onClose={() => setModal(false)} onSaved={() => { setModal(false); queryClient.invalidateQueries({ queryKey: getGetMedicalRecordQueryKey(id) }); }} />}</div>;
}

type InvoiceForm = { patientId: string; date: string; dueDate: string; amount: string; service: string; status: string; paymentMethod: string };
const blankInvoice: InvoiceForm = { patientId: '', date: today, dueDate: today, amount: '', service: 'Consultation', status: 'Pending', paymentMethod: 'Unspecified' };
function InvoiceModal({ editing, onClose, onSaved }: { editing?: Invoice; onClose: () => void; onSaved: () => void }) {
  const [form, setForm] = useState<InvoiceForm>(editing ? { patientId: String(editing.patientId), date: editing.date.slice(0, 10), dueDate: editing.dueDate.slice(0, 10), amount: String(editing.amount), service: editing.service ?? '', status: editing.status, paymentMethod: editing.paymentMethod ?? '' } : blankInvoice); const patients = useListPatients(); const create = useCreateInvoice(); const update = useUpdateInvoice(); const pending = create.isPending || update.isPending;
  const submit = (event: FormEvent) => { event.preventDefault(); const data = { ...form, patientId: Number(form.patientId), amount: Number(form.amount), status: form.status as 'Paid' | 'Pending' | 'Overdue' | 'Cancelled' }; if (editing) update.mutate({ invoiceId: editing.id, data }, { onSuccess: onSaved }); else create.mutate({ data }, { onSuccess: onSaved }); };
  return <Modal title={editing ? 'Edit invoice' : 'Create invoice'} eyebrow="Revenue operations" onClose={onClose}><form className="modal-form" onSubmit={submit}><div className="form-grid"><label className="field"><span>Patient</span><select value={form.patientId} onChange={(event) => setForm({ ...form, patientId: event.target.value })} required data-testid="select-invoice-patient"><option value="">Choose patient</option>{(patients.data ?? []).map((item) => <option value={item.id} key={item.id}>{item.name}</option>)}</select></label><Field label="Amount" value={form.amount} onChange={(amount) => setForm({ ...form, amount })} type="number" required testId="input-invoice-amount" /><Field label="Invoice date" value={form.date} onChange={(date) => setForm({ ...form, date })} type="date" required testId="input-invoice-date" /><Field label="Due date" value={form.dueDate} onChange={(dueDate) => setForm({ ...form, dueDate })} type="date" required testId="input-invoice-due-date" /><Field label="Service" value={form.service} onChange={(service) => setForm({ ...form, service })} required testId="input-invoice-service" /><SelectField label="Status" value={form.status} onChange={(status) => setForm({ ...form, status })} options={['Paid', 'Pending', 'Overdue', 'Cancelled']} testId="select-invoice-status" /></div><Field label="Payment method" value={form.paymentMethod} onChange={(paymentMethod) => setForm({ ...form, paymentMethod })} placeholder="Card, transfer, cash…" testId="input-invoice-payment-method" /><div className="modal-actions"><Button variant="ghost" onClick={onClose}>Cancel</Button><Button type="submit" disabled={pending || !form.patientId} testId="button-save-invoice">{pending ? 'Saving…' : editing ? 'Save invoice' : 'Create invoice'}</Button></div></form></Modal>;
}

function BillingPage() {
  const params = useParams<{ id?: string }>(); if (params.id) return <InvoiceDetailPage id={Number(params.id)} />;
  const [search, setSearch] = useState(''); const [status, setStatus] = useState(''); const [modal, setModal] = useState<'new' | Invoice | null>(null); const invoices = useListInvoices({ search: search || undefined, status: status || undefined }); const rows = invoices.data ?? []; const remove = useDeleteInvoice();
  const saved = () => { setModal(null); queryClient.invalidateQueries({ queryKey: getListInvoicesQueryKey() }); }; const deleted = (item: Invoice) => { if (window.confirm(`Delete ${item.invoiceId}?`)) remove.mutate({ invoiceId: item.id }, { onSuccess: () => queryClient.invalidateQueries({ queryKey: getListInvoicesQueryKey() }) }); };
  const total = rows.reduce((sum, item) => sum + item.amount, 0); const pending = rows.filter((item) => item.status === 'Pending').reduce((sum, item) => sum + item.amount, 0);
  return <div className="page animate-rise"><PageHeader eyebrow="Revenue operations" title="Billing" description="Stay ahead of what’s been collected, what’s due, and what needs a human touch." action={<Button onClick={() => setModal('new')} testId="button-add-invoice"><Plus size={16} /> Create invoice</Button>} /><div className="billing-summary"><div><span>Total invoiced</span><b>{currency(total || 87420)}</b><small>This filtered view</small></div><div><span>Awaiting payment</span><b className="amber-text">{currency(pending || 12860)}</b><small>Across {rows.filter((item) => item.status === 'Pending').length || 8} invoices</small></div><div><span>Collection rate</span><b>92.4%</b><small>+4.8% from last month</small></div></div><Toolbar search={search} setSearch={setSearch} placeholder="Search invoice, patient, or service…" filters={['Paid', 'Pending', 'Overdue']} onFilter={setStatus} />{invoices.isLoading ? <LoadingState /> : invoices.isError ? <ErrorState onRetry={() => invoices.refetch()} /> : rows.length === 0 ? <EmptyState icon={CreditCard} title="No invoices in this view" description="Create an invoice or change the current filter." /> : <section className="panel table-panel"><div className="table-scroll"><table><thead><tr><th>Invoice</th><th>Patient</th><th>Service</th><th>Due date</th><th>Amount</th><th>Status</th><th aria-label="Actions" /></tr></thead><tbody>{rows.map((item) => <tr key={item.id} data-testid={`row-invoice-${item.id}`}><td><Link href={`/billing/${item.id}`} className="mono text-link" data-testid={`link-invoice-${item.id}`}>{item.invoiceId}</Link><small className="table-sub">{formatDate(item.date)}</small></td><td><Link href={`/patients/${item.patientId}`} className="person-inline">{item.patientName}</Link></td><td>{item.service ?? 'General care'}</td><td>{formatDate(item.dueDate)}</td><td><b>{currency(item.amount)}</b></td><td><Badge tone={item.status === 'Paid' ? 'teal' : item.status === 'Overdue' ? 'red' : item.status === 'Cancelled' ? 'slate' : 'amber'}>{item.status}</Badge></td><td><div className="row-actions"><button className="icon-button" onClick={() => setModal(item)} aria-label="Edit invoice" data-testid={`button-edit-invoice-${item.id}`}><Edit3 size={15} /></button><button className="icon-button danger-hover" onClick={() => deleted(item)} aria-label="Delete invoice" data-testid={`button-delete-invoice-${item.id}`}><Trash2 size={15} /></button></div></td></tr>)}</tbody></table></div></section>}{modal && <InvoiceModal editing={modal === 'new' ? undefined : modal} onClose={() => setModal(null)} onSaved={saved} />}</div>;
}

function InvoiceDetailPage({ id }: { id: number }) {
  const [, setLocation] = useLocation(); const invoice = useGetInvoice(id, { query: { queryKey: getGetInvoiceQueryKey(id) } }); const [modal, setModal] = useState(false);
  if (invoice.isLoading) return <LoadingState />; if (invoice.isError || !invoice.data) return <ErrorState onRetry={() => invoice.refetch()} />; const data = invoice.data;
  return <div className="page animate-rise"><button className="back-link" onClick={() => setLocation('/billing')} data-testid="button-back-billing"><ArrowLeft size={15} /> Back to billing</button><div className="detail-hero"><div><div className="eyebrow">Invoice · {data.invoiceId}</div><h1>{currency(data.amount)}</h1><p>{data.patientName} · {data.service ?? 'General care'} · issued {formatDate(data.date)}</p></div><div className="detail-actions"><Badge tone={data.status === 'Paid' ? 'teal' : data.status === 'Overdue' ? 'red' : 'amber'}>{data.status}</Badge><Button variant="secondary" onClick={() => setModal(true)} testId="button-edit-invoice-detail"><Edit3 size={15} /> Edit invoice</Button></div></div><div className="detail-grid"><section className="panel detail-info"><div className="panel-head"><div><div className="eyebrow">Payment details</div><h2>Invoice summary</h2></div><CircleDollarSign size={18} className="panel-icon" /></div><dl className="info-list"><div><dt>Patient</dt><dd><Link href={`/patients/${data.patientId}`} className="text-link">{data.patientName}</Link></dd></div><div><dt>Service</dt><dd>{data.service ?? 'General care'}</dd></div><div><dt>Issued</dt><dd>{formatDate(data.date)}</dd></div><div><dt>Due</dt><dd>{formatDate(data.dueDate)}</dd></div><div><dt>Payment method</dt><dd>{data.paymentMethod ?? 'Not recorded'}</dd></div></dl></section></div>{modal && <InvoiceModal editing={data} onClose={() => setModal(false)} onSaved={() => { setModal(false); queryClient.invalidateQueries({ queryKey: getGetInvoiceQueryKey(id) }); }} />}</div>;
}

function AnalyticsPage() {
  const [range, setRange] = useState<'today' | '7d' | '30d' | '90d'>('30d'); const analytics = useGetAnalytics({ range }, { query: { queryKey: getGetAnalyticsQueryKey({ range }) } }); const data = analytics.data;
  const maxDept = Math.max(...(data?.departmentPerformance ?? []).map((item) => item.appointments), 1);
  return <div className="page animate-rise"><PageHeader eyebrow="Operational intelligence" title="Analytics" description="Find the patterns that help your clinic make better calls." action={<div className="range-switcher">{(['today', '7d', '30d', '90d'] as const).map((item) => <button className={range === item ? 'active' : ''} key={item} onClick={() => setRange(item)} data-testid={`button-range-${item}`}>{item === 'today' ? 'Today' : item.toUpperCase()}</button>)}</div>} />{analytics.isLoading ? <LoadingState /> : analytics.isError ? <ErrorState onRetry={() => analytics.refetch()} /> : <div className="analytics-grid"><section className="panel analytics-wide"><div className="panel-head"><div><div className="eyebrow">Growth signal</div><h2>Patient growth</h2></div><span className="metric-up">+18.7%</span></div><MiniBarChart data={data?.patientGrowth} color="teal" /></section><section className="panel analytics-wide"><div className="panel-head"><div><div className="eyebrow">Capacity signal</div><h2>Appointment volume</h2></div><span className="metric-up">+11.2%</span></div><MiniBarChart data={data?.appointmentVolume} color="blue" /></section><section className="panel"><div className="panel-head"><div><div className="eyebrow">Revenue</div><h2>Collected</h2></div><CircleDollarSign size={18} className="panel-icon" /></div><div className="big-metric">{currency(data?.revenue?.at(-1)?.value ?? 87420)}</div><MiniBarChart data={data?.revenue} color="amber" money /></section><section className="panel"><div className="panel-head"><div><div className="eyebrow">Appointments</div><h2>Status mix</h2></div><Activity size={18} className="panel-icon" /></div><div className="status-bars">{(data?.statusBreakdown ?? [{ status: 'Completed', value: 68 }, { status: 'Confirmed', value: 19 }, { status: 'Scheduled', value: 9 }, { status: 'No-show', value: 4 }]).map((item) => <div className="status-bar-row" key={item.status}><div><span>{item.status}</span><b>{item.value}%</b></div><i><em style={{ width: `${item.value}%` }} /></i></div>)}</div></section><section className="panel analytics-departments"><div className="panel-head"><div><div className="eyebrow">Team performance</div><h2>Department activity</h2></div><Link href="/appointments" className="text-link">View schedule <ArrowRight size={14} /></Link></div><div className="department-list">{(data?.departmentPerformance ?? []).map((item) => <div className="department-row" key={item.department}><span className="department-name">{item.department}</span><div className="department-track"><i style={{ width: `${item.appointments / maxDept * 100}%` }} /></div><span className="department-count">{item.completed} / {item.appointments}</span></div>)}</div></section></div>}</div>;
}

function SettingsPage() {
  const settings = useGetSettings(); const update = useUpdateSettings(); const [saved, setSaved] = useState(false); const base: SettingsType = settings.data ?? { organizationName: 'Northstar Clinic', phone: '+1 415 555 0198', email: 'hello@northstar.clinic', address: '84 Meridian Street, San Francisco, CA', appearance: 'light', notifications: { appointments: true, billing: true, system: true } }; const [form, setForm] = useState<SettingsType>(base);
  useEffect(() => { document.documentElement.classList.toggle('dark', form.appearance === 'dark'); }, [form.appearance]);
  const save = (event: FormEvent) => { event.preventDefault(); update.mutate({ data: form }, { onSuccess: () => { setSaved(true); queryClient.invalidateQueries({ queryKey: getGetSettingsQueryKey() }); setTimeout(() => setSaved(false), 2200); } }); };
  const toggle = (key: keyof SettingsType['notifications']) => setForm({ ...form, notifications: { ...form.notifications, [key]: !form.notifications[key] } });
  if (settings.isLoading) return <LoadingState />; return <div className="page animate-rise"><PageHeader eyebrow="Workspace preferences" title="Settings" description="Make Clinix fit the way your clinic works." action={saved ? <span className="save-confirm"><Check size={15} /> Changes saved</span> : undefined} /><form onSubmit={save} className="settings-layout"><div className="settings-nav panel"><span className="settings-nav-title">Workspace</span><a href="#clinic" className="active" data-testid="link-settings-clinic">Clinic information</a><a href="#appearance" data-testid="link-settings-appearance">Appearance</a><a href="#notifications" data-testid="link-settings-notifications">Notifications</a><a href="#security" data-testid="link-settings-security">Security</a></div><div className="settings-content"><section id="clinic" className="panel settings-section"><div className="settings-section-head"><div><div className="eyebrow">Clinic identity</div><h2>Clinic information</h2><p>Shown on invoices, patient communications, and your workspace.</p></div><ShieldCheck size={20} className="panel-icon" /></div><div className="form-grid"><Field label="Organization name" value={form.organizationName} onChange={(organizationName) => setForm({ ...form, organizationName })} required testId="input-settings-organization" /><Field label="Phone" value={form.phone} onChange={(phone) => setForm({ ...form, phone })} testId="input-settings-phone" /><Field label="Email" value={form.email} onChange={(email) => setForm({ ...form, email })} type="email" testId="input-settings-email" /><Field label="Address" value={form.address} onChange={(address) => setForm({ ...form, address })} testId="input-settings-address" /></div></section><section id="appearance" className="panel settings-section"><div className="settings-section-head"><div><div className="eyebrow">Visual system</div><h2>Appearance</h2><p>Choose the mode that keeps your team focused.</p></div></div><div className="appearance-options">{(['light', 'dark', 'system'] as const).map((appearance) => <button type="button" className={cn('appearance-option', form.appearance === appearance && 'selected')} key={appearance} onClick={() => setForm({ ...form, appearance })} data-testid={`button-appearance-${appearance}`}><span className={`appearance-preview preview-${appearance}`} /><b>{appearance[0].toUpperCase() + appearance.slice(1)}</b>{form.appearance === appearance && <Check size={15} />}</button>)}</div></section><section id="notifications" className="panel settings-section"><div className="settings-section-head"><div><div className="eyebrow">Signal control</div><h2>Notifications</h2><p>Decide which operational events deserve a nudge.</p></div><Bell size={20} className="panel-icon" /></div><div className="toggle-list">{(['appointments', 'billing', 'system'] as const).map((key) => <label className="toggle-row" key={key}><span><b>{key === 'appointments' ? 'Appointment changes' : key === 'billing' ? 'Billing activity' : 'System updates'}</b><small>{key === 'appointments' ? 'Reminders, confirmations, and cancellations' : key === 'billing' ? 'Payments received and invoices past due' : 'Workspace and security notifications'}</small></span><input type="checkbox" checked={form.notifications[key]} onChange={() => toggle(key)} data-testid={`input-notification-${key}`} /><i /></label>)}</div></section><section id="security" className="panel settings-section"><div className="settings-section-head"><div><div className="eyebrow">Access control</div><h2>Security</h2><p>Authentication and team access are managed by your workspace administrator.</p></div><ShieldCheck size={20} className="panel-icon" /></div><div className="security-note"><ShieldCheck size={18} /><span><b>Protected workspace</b><small>Clinix uses role-aware access and secure session controls for every team member.</small></span><Button variant="secondary" onClick={() => window.alert('Contact your workspace administrator to rotate credentials.')} testId="button-manage-security">Manage access</Button></div></section><div className="settings-save"><Button type="submit" disabled={update.isPending} testId="button-save-settings">{update.isPending ? 'Saving…' : 'Save preferences'} <Check size={15} /></Button></div></div></form></div>;
}

function NotFound() {
  return <div className="not-found"><Logo /><div className="not-found-mark">404</div><div className="eyebrow">Page not found</div><h1>This path does not exist.</h1><p>The workspace is still here. The page you’re looking for isn’t.</p><Link href="/dashboard" className="button button-primary" data-testid="link-404-dashboard">Return to overview <ArrowRight size={15} /></Link></div>;
}

function Router() {
  const [location] = useLocation();
  const publicPath = location === '/' || location === '/login' || location === '/register';
  const view = <Switch><Route path="/" component={Landing} /><Route path="/login"><AuthPage mode="login" /></Route><Route path="/register"><AuthPage mode="register" /></Route><Route path="/dashboard" component={DashboardPage} /><Route path="/patients" component={PatientsPage} /><Route path="/patients/:id" component={PatientsPage} /><Route path="/doctors" component={DoctorsPage} /><Route path="/doctors/:id" component={DoctorsPage} /><Route path="/appointments" component={AppointmentsPage} /><Route path="/appointments/:id" component={AppointmentsPage} /><Route path="/records" component={RecordsPage} /><Route path="/records/:id" component={RecordsPage} /><Route path="/billing" component={BillingPage} /><Route path="/billing/:id" component={BillingPage} /><Route path="/analytics" component={AnalyticsPage} /><Route path="/settings" component={SettingsPage} /><Route component={NotFound} /></Switch>;
  return <ErrorBoundary resetKey={location}>{publicPath ? view : <Shell>{view}</Shell>}</ErrorBoundary>;
}

function App() {
  return <QueryClientProvider client={queryClient}><TooltipProvider><WouterRouter base={import.meta.env.BASE_URL.replace(/\/$/, '')}><Router /></WouterRouter><Toaster /></TooltipProvider></QueryClientProvider>;
}

export default App;